package org.fen.fen.service;
import org.fen.fen.domain.*; import org.fen.fen.recuperacaosenha.dto.*; import org.fen.fen.repository.*; import org.junit.jupiter.api.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class SolicitacaoRecuperacaoSenhaServiceTest {
 private final SolicitacaoRecuperacaoSenhaRepository requests=mock(SolicitacaoRecuperacaoSenhaRepository.class); private final UsuarioRepository users=mock(UsuarioRepository.class); private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(); private SolicitacaoRecuperacaoSenhaService service;
 @BeforeEach void setup(){service=new SolicitacaoRecuperacaoSenhaService(requests,users,encoder);}
 @Test void criaSomenteHashDaNovaSenha(){Usuario u=new Usuario();u.setEmail("a@fen.br");when(users.findByEmailIgnoreCase("a@fen.br")).thenReturn(Optional.of(u));when(requests.saveAndFlush(any())).thenAnswer(i->{var s=i.getArgument(0,SolicitacaoRecuperacaoSenha.class);s.setId(UUID.randomUUID());return s;});service.criar(new SolicitacaoRecuperacaoSenhaRequest("a@fen.br","senhaNova1"));var saved=org.mockito.ArgumentCaptor.forClass(SolicitacaoRecuperacaoSenha.class);verify(requests).saveAndFlush(saved.capture());assertThat(saved.getValue().getNovaSenhaHash()).isNotEqualTo("senhaNova1");assertThat(encoder.matches("senhaNova1",saved.getValue().getNovaSenhaHash())).isTrue();}
 @Test void impedeReprocessarSolicitacaoFinalizada(){SolicitacaoRecuperacaoSenha s=new SolicitacaoRecuperacaoSenha(new Usuario(),"hash");s.setStatus(StatusSolicitacaoRecuperacaoSenha.APROVADA);when(requests.buscarDetalhe(any())).thenReturn(Optional.of(s));assertThatThrownBy(()->service.aprovar(UUID.randomUUID())).isInstanceOf(IllegalStateException.class);}
}
